  pthread_mutex_lock(&s_voice.lock);
  subscribed = s_voice.button_subscribed;
  s_voice.button_subscribed = false;
  pthread_mutex_unlock(&s_voice.lock);

  if (subscribed) {
    aic_button_unsubscribe(voice_button_cb, NULL);
  }
}
