        else if (strcmp(cmd, "set_weixin_token") == 0)
            cmd_set_weixin_token(argc, argv);
        else if (strcmp(cmd, "weixin_login") == 0)
            cmd_weixin_login();
        else if (strcmp(cmd, "launch_app") == 0)
            cmd_launch_app(argc, argv);
        else if (strcmp(cmd, "exit_app") == 0)
