                                 audio_playback_fifo_worker, pb);
            pthread_attr_destroy(&attr);
            if (ret != 0) {
              syslog(LOG_WARNING, "[%s] fifo thread failed: %d\n", TAG, ret);
              audio_playback_disable_fifo(pb);
            } else {
              pb->fifo_thread_started = true;
              pb->fifo_started = true;
              syslog(LOG_INFO, "[%s] fifo playback started: %s\n",
                     TAG, PB_FIFO_PATH);
            }
          }
        } else {
          syslog(LOG_WARNING, "[%s] nxplayer_playraw fifo failed\n", TAG);
          nxplayer_release(pb->player);
          pb->player = NULL;
          close(pb->fifo_fd);
          pb->fifo_fd = -1;
          unlink(PB_FIFO_PATH);
        }
      } else {
        close(pb->fifo_fd);
        pb->fifo_fd = -1;
        unlink(PB_FIFO_PATH);
      }
    } else {
      unlink(PB_FIFO_PATH);
    }
  }
#endif

  syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit)\n",
         TAG, sample_rate, channels, bits_per_sample);
  return pb;
}

int audio_playback_write(audio_playback_t *pb,
                         const void *buf, size_t len)
{
  const unsigned char *src;
  size_t off = 0;

  if (pb == NULL || pb->tmp_fd < 0 || buf == NULL || len == 0) {
    return -EINVAL;
  }

  src = (const unsigned char *)buf;
  while (off < len) {
    ssize_t n = write(pb->tmp_fd, src + off, len - off);
    if (n < 0) {
      if (errno == EINTR) {
        continue;
      }
      pb->write_error = errno == 0 ? EIO : errno;
      return -pb->write_error;
    }
    if (n == 0) {
      pb->write_error = EIO;
      return -EIO;
    }
    off += (size_t)n;
  }

  pb->total_written += off;
#ifdef CONFIG_SYSTEM_NXPLAYER
  (void)audio_playback_fifo_enqueue(pb, src, len);
#endif
  return (int)off;
}

