void audio_playback_close(audio_playback_t *pb)
{
  if (pb == NULL) {
    return;
  }

  if (pb->tmp_fd >= 0) {
    close(pb->tmp_fd);
    pb->tmp_fd = -1;
  }

#ifdef CONFIG_SYSTEM_NXPLAYER
  audio_playback_stop_fifo_thread(pb);
  if (pb->fifo_fd >= 0) {
    close(pb->fifo_fd);
    pb->fifo_fd = -1;
  }
  if (pb->player != NULL) {
    nxplayer_release(pb->player);
    pb->player = NULL;
  }
#endif

  if (pb->write_error != 0) {
    syslog(LOG_ERR, "[%s] PCM write failed: %d\n",
           TAG, pb->write_error);
    goto out;
  }

  if (pb->total_written == 0) {
    syslog(LOG_WARNING, "[%s] no PCM data to play\n", TAG);
    goto out;
  }

