static int mimo_tts_emit_pcm(mimo_tts_stream_ctx_t *ctx,
                             const unsigned char *pcm, size_t len)
{
  if (ctx->cb == NULL || pcm == NULL || len == 0) {
    return 0;
  }

  ctx->cb(pcm, len, 0, ctx->user_data);
  ctx->chunks++;
  return 0;
}

static int mimo_tts_flush_pending(mimo_tts_stream_ctx_t *ctx, bool final)
{
  size_t decode_len;
  size_t out_len = 0;
  size_t padded_len = 0;
  char *src = ctx->b64;
  int ret;

  if (ctx->b64_len == 0) {
    return 0;
  }

  decode_len = final ? ctx->b64_len : (ctx->b64_len / 4) * 4;
  if (decode_len == 0) {
    return 0;
  }

  if (final && (decode_len % 4) != 0) {
    padded_len = ((decode_len + 3) / 4) * 4;
    if (ensure_b64_cap(ctx, padded_len + 1) < 0) {
      return -ENOMEM;
    }
    memset(ctx->b64 + ctx->b64_len, '=', padded_len - ctx->b64_len);
    ctx->b64[padded_len] = '\0';
    src = ctx->b64;
    decode_len = padded_len;
  }

  if (decode_len == 0) {
    return 0;
  }

  if (ensure_pcm_cap(ctx, (decode_len / 4) * 3 + 8) < 0) {
    return -ENOMEM;
  }

  ret = mbedtls_base64_decode(ctx->pcm, ctx->pcm_cap, &out_len,
                              (const unsigned char *)src, decode_len);
  if (ret != 0) {
    return -EPROTO;
  }

  if (out_len > 0) {
    (void)mimo_tts_emit_pcm(ctx, ctx->pcm, out_len);
  }

  if (final) {
    ctx->b64_len = 0;
    ctx->b64[0] = '\0';
  } else if (ctx->b64_len > decode_len) {
    memmove(ctx->b64, ctx->b64 + decode_len, ctx->b64_len - decode_len);
    ctx->b64_len -= decode_len;
    ctx->b64[ctx->b64_len] = '\0';
  } else {
    ctx->b64_len = 0;
    ctx->b64[0] = '\0';
  }

  return 0;
}

static int mimo_tts_process_line(mimo_tts_stream_ctx_t *ctx, const char *line)
{
  const char *payload = line;
  cJSON *root;
  const char *frag;
  cJSON *error;

  if (payload == NULL) {
    return 0;
  }

  while (*payload == ' ' || *payload == '\t') {
    payload++;
  }
  if (*payload == '\0') {
    return 0;
  }

  if (strncmp(payload, "event:", 6) == 0 ||
      strncmp(payload, "id:", 3) == 0 ||
      strncmp(payload, "retry:", 6) == 0) {
    return 0;
  }

  if (strncmp(payload, "data:", 5) == 0) {
    payload += 5;
    while (*payload == ' ' || *payload == '\t') {
      payload++;
    }
  }

  if (strcmp(payload, "[DONE]") == 0) {
    return mimo_tts_flush_pending(ctx, true);
  }

  root = cJSON_Parse(payload);
  if (root == NULL) {
    if (payload[0] != '{' && payload[0] != '[') {
      return 0;
    }
    syslog(LOG_WARNING, "[%s] bad SSE JSON: %.120s\n", TAG, payload);
    return 0;
  }

  error = cJSON_GetObjectItem(root, "error");
  if (error != NULL) {
    cJSON *msg = cJSON_GetObjectItem(error, "message");
    syslog(LOG_ERR, "[%s] SSE error: %.120s\n",
           TAG, cJSON_IsString(msg) ? msg->valuestring : payload);
    cJSON_Delete(root);
    return -EIO;
  }

  frag = extract_audio_fragment(root);
  if (frag != NULL && frag[0] != '\0') {
    int ret = mimo_tts_append_fragment(ctx, frag);
    if (ret < 0) {
      cJSON_Delete(root);
      return ret;
    }
    ret = mimo_tts_flush_pending(ctx, false);
    if (ret < 0) {
      cJSON_Delete(root);
      return ret;
    }
  }

  cJSON_Delete(root);
  return 0;
}

static int mimo_tts_body_cb(const char *data, size_t len, void *user_data)
{
  mimo_tts_stream_ctx_t *ctx = (mimo_tts_stream_ctx_t *)user_data;
  size_t pos = 0;

  if (ctx == NULL || data == NULL || len == 0) {
    return 0;
  }

  while (pos < len) {
    char c = data[pos++];

    if (ensure_line_cap(ctx, ctx->line_len + 2) < 0) {
      return -ENOMEM;
    }

    if (c == '\r') {
      continue;
    }

    if (c == '\n') {
      ctx->line[ctx->line_len] = '\0';
      if (ctx->line_len > 0) {
        int ret = mimo_tts_process_line(ctx, ctx->line);
        ctx->line_len = 0;
        if (ret < 0) {
          ctx->err = ret;
          return ret;
        }
      } else {
        ctx->line_len = 0;
      }
      continue;
    }

    ctx->line[ctx->line_len++] = c;
  }

  return 0;
}

static char *build_tts_body(const char *text, size_t *body_len)
{
  static const char prefix_fmt[] =
    "{\"model\":\"%s\",\"messages\":[{\"role\":\"assistant\","
    "\"content\":\"";
  static const char suffix[] =
    "\"}],\"modalities\":[\"text\",\"audio\"],"
    "\"audio\":{\"format\":\"pcm16\",\"voice\":\"";
  static const char tail[] = "\"},\"stream\":true}";
  size_t need;
  size_t prefix_len;
  size_t text_len;
  size_t total;
  char prefix[256];
  char *body;
  int n;

  if (text == NULL) {
    return NULL;
  }

  n = snprintf(prefix, sizeof(prefix), prefix_fmt, s_model);
  if (n < 0 || (size_t)n >= sizeof(prefix)) {
    return NULL;
  }

  prefix_len = (size_t)n;
  text_len = strlen(text);
  need = prefix_len + text_len * 2 + sizeof(suffix) - 1 +
         strlen(s_voice) + sizeof(tail) - 1 + 1;
  body = malloc(need);
  if (body == NULL) {
    return NULL;
  }

  memcpy(body, prefix, prefix_len);
  total = prefix_len;

  for (size_t i = 0; i < text_len; i++) {
    char ch = text[i];
    if (ch == '\\' || ch == '\"') {
      body[total++] = '\\';
    }
    else if (ch == '\n') {
      body[total++] = '\\';
      body[total++] = 'n';
      continue;
    }
    else if (ch == '\r') {
      body[total++] = '\\';
      body[total++] = 'r';
      continue;
    }
    else if (ch == '\t') {
      body[total++] = '\\';
      body[total++] = 't';
      continue;
    }
    body[total++] = ch;
  }

  memcpy(body + total, suffix, sizeof(suffix) - 1);
  total += sizeof(suffix) - 1;
  memcpy(body + total, s_voice, strlen(s_voice));
  total += strlen(s_voice);
  memcpy(body + total, tail, sizeof(tail) - 1);
  total += sizeof(tail) - 1;
  body[total] = '\0';
  if (body_len != NULL) {
    *body_len = total;
  }
  return body;
}

static void mimo_tts_collect_cb(const unsigned char *pcm_data,
                                size_t pcm_len,
                                int is_last,
                                void *user_data)
{
  mimo_tts_collect_ctx_t *collect = user_data;

  if (is_last) {
    return;
  }
  if (pcm_data == NULL || pcm_len == 0 || collect == NULL) {
    return;
  }
  if (collect->len + pcm_len > collect->cap) {
    collect->err = -ENOSPC;
    return;
  }
  memcpy(collect->buf + collect->len, pcm_data, pcm_len);
  collect->len += pcm_len;
}

static int mimo_tts_synthesize_stream(const char *text,
                                      voice_tts_chunk_cb cb,
                                      void *user_data)
{
  mimo_tts_stream_ctx_t ctx;
  char *body = NULL;
  char auth[192];
  size_t body_len = 0;
  int http_status = 0;
  int ret;

  if (text == NULL || cb == NULL) {
    return -EINVAL;
  }

  memset(&ctx, 0, sizeof(ctx));
  ctx.cb = cb;
  ctx.user_data = user_data;

  mimo_tts_init();
  if (s_api_key[0] == '\0') {
    syslog(LOG_ERR, "[%s] API key not configured\n", TAG);
    return -ENOENT;
  }

  body = build_tts_body(text, &body_len);
  if (body == NULL) {
    return -ENOMEM;
  }

  snprintf(auth, sizeof(auth), "Bearer %s", s_api_key);
  vela_header_t hdrs[] = {
    { "Content-Type", "application/json" },
    { "Accept", "text/event-stream" },
    { "Authorization", auth },
    { "api-key", s_api_key },
    { "Connection", "close" },
    { NULL, NULL }
  };

  syslog(LOG_INFO, "[%s] stream request: text=%zu bytes host=%s model=%s\n",
         TAG, strlen(text), s_host, s_model);
  ret = vela_https_request_stream(s_host, s_port, "POST", s_path,
                                  hdrs, body, body_len,
                                  mimo_tts_body_cb, &ctx, &http_status);
  free(body);

  if (ret < 0) {
    syslog(LOG_ERR, "[%s] stream request failed: %d\n", TAG, ret);
    mimo_tts_stream_free(&ctx);
    return ret;
  }

  if (http_status != 200) {
    syslog(LOG_ERR, "[%s] HTTP %d during stream\n", TAG, http_status);
    mimo_tts_stream_free(&ctx);
    return -EIO;
  }

  if (ctx.err < 0) {
    ret = ctx.err;
  } else {
    ret = mimo_tts_flush_pending(&ctx, true);
    if (ret == 0 && ctx.chunks > 0) {
      cb(NULL, 0, 1, user_data);
    }
  }

  if (ret == 0 && ctx.chunks == 0) {
    ret = -ENODATA;
  }

  mimo_tts_stream_free(&ctx);
  return ret;
}

static int mimo_tts_synthesize(const char *text,
                               unsigned char *pcm_out,
                               size_t pcm_cap,
                               size_t *pcm_len)
{
  mimo_tts_collect_ctx_t collect = {
    .buf = pcm_out,
    .len = 0,
    .cap = pcm_cap,
    .err = 0,
  };
  int ret;

  if (text == NULL || pcm_out == NULL || pcm_len == NULL) {
    return -EINVAL;
  }

  ret = mimo_tts_synthesize_stream(text, mimo_tts_collect_cb, &collect);
  if (collect.err < 0) {
    ret = collect.err;
  }
  if (ret == 0) {
    *pcm_len = collect.len;
  }
  return ret;
}

static const voice_tts_ops_t s_mimo_tts_ops = {
  .name = "mimo",
  .init = mimo_tts_init,
  .synthesize = mimo_tts_synthesize,
  .synthesize_stream = mimo_tts_synthesize_stream,
  .deinit = NULL,
};

int mimo_tts_register(void)
{
  return voice_tts_register(&s_mimo_tts_ops);
}

