static void *xrealloc(void *ptr, size_t new_cap)
{
  void *mem = realloc(ptr, new_cap);
  return mem;
}

static int ensure_line_cap(mimo_tts_stream_ctx_t *ctx, size_t need)
{
  if (need <= ctx->line_cap) {
    return 0;
  }

  size_t cap = ctx->line_cap ? ctx->line_cap : 1024;
  while (cap < need) {
    cap *= 2;
  }

  char *line = xrealloc(ctx->line, cap);
  if (line == NULL) {
    return -ENOMEM;
  }

  ctx->line = line;
  ctx->line_cap = cap;
  return 0;
}

static int ensure_b64_cap(mimo_tts_stream_ctx_t *ctx, size_t need)
{
  if (need <= ctx->b64_cap) {
    return 0;
  }

  size_t cap = ctx->b64_cap ? ctx->b64_cap : 1024;
  while (cap < need) {
    cap *= 2;
  }

  char *b64 = xrealloc(ctx->b64, cap);
  if (b64 == NULL) {
    return -ENOMEM;
  }

  ctx->b64 = b64;
  ctx->b64_cap = cap;
  return 0;
}

static int ensure_pcm_cap(mimo_tts_stream_ctx_t *ctx, size_t need)
{
  if (need <= ctx->pcm_cap) {
    return 0;
  }

  size_t cap = ctx->pcm_cap ? ctx->pcm_cap : 4096;
  while (cap < need) {
    cap *= 2;
  }

  unsigned char *pcm = xrealloc(ctx->pcm, cap);
  if (pcm == NULL) {
    return -ENOMEM;
  }

  ctx->pcm = pcm;
  ctx->pcm_cap = cap;
  return 0;
}

static void mimo_tts_stream_free(mimo_tts_stream_ctx_t *ctx)
{
  if (ctx == NULL) {
    return;
  }

  free(ctx->line);
  free(ctx->b64);
  free(ctx->pcm);
  memset(ctx, 0, sizeof(*ctx));
}

static int mimo_tts_init(void)
{
  memset(s_api_key, 0, sizeof(s_api_key));

  if (claw_config_get(VELACLAW_CFG_KEY_MIMO_API_KEY,
                      s_api_key, sizeof(s_api_key)) != OK ||
      s_api_key[0] == '\0') {
    (void)claw_config_get(VELACLAW_CFG_KEY_API_KEY,
                          s_api_key, sizeof(s_api_key));
  }

  if (s_api_key[0] == '\0' && VELACLAW_SECRET_API_KEY[0] != '\0') {
    snprintf(s_api_key, sizeof(s_api_key), "%s", VELACLAW_SECRET_API_KEY);
  }

  config_get_or_default(VELACLAW_CFG_KEY_MIMO_HOST,
                        VELACLAW_MIMO_HOST, s_host, sizeof(s_host));
  config_get_or_default(VELACLAW_CFG_KEY_MIMO_PORT,
                        VELACLAW_MIMO_PORT, s_port, sizeof(s_port));
  config_get_or_default(VELACLAW_CFG_KEY_MIMO_PATH,
                        VELACLAW_MIMO_PATH, s_path, sizeof(s_path));
  config_get_or_default(VELACLAW_CFG_KEY_MIMO_TTS_MODEL,
                        VELACLAW_MIMO_TTS_MODEL, s_model, sizeof(s_model));
  config_get_or_default(VELACLAW_CFG_KEY_MIMO_TTS_VOICE,
                        VELACLAW_MIMO_TTS_VOICE, s_voice, sizeof(s_voice));
  normalize_token_plan_host();

  return 0;
}

