  if (pb == NULL || pb->fifo_fd < 0 || buf == NULL || len == 0) {
    return 0;
  }

  while (off < len) {
    ssize_t n = write(pb->fifo_fd, buf + off, len - off);
    if (n > 0) {
      off += (size_t)n;
      pb->fifo_written += (size_t)n;
      continue;
    }
    if (n < 0 && errno == EINTR) {
      continue;
    }
    if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) {
      if (waited_ms >= VELACLAW_VOICE_TTS_PIPE_STALL_MS) {
        pb->fifo_error = -EAGAIN;
        return -EAGAIN;
      }
      usleep(10 * 1000);
      waited_ms += 10;
      continue;
    }

    pb->fifo_error = (errno == 0) ? -EIO : -errno;
    return pb->fifo_error;
  }

  return 0;
}

static void audio_playback_queue_append_locked(struct audio_playback *pb,
                                               const unsigned char *buf,
                                               size_t len)
{
  size_t tail = (pb->fifo_queue_head + pb->fifo_queue_len) %
                pb->fifo_queue_cap;
  size_t first = pb->fifo_queue_cap - tail;

  if (first > len) {
    first = len;
  }

  memcpy(pb->fifo_queue + tail, buf, first);
  if (len > first) {
    memcpy(pb->fifo_queue, buf + first, len - first);
  }
  pb->fifo_queue_len += len;
}

static size_t audio_playback_queue_pop_locked(struct audio_playback *pb,
                                              unsigned char *buf,
                                              size_t cap)
{
  size_t take;
  size_t first;

  if (pb->fifo_queue_len == 0 || cap == 0) {
    return 0;
  }

  take = pb->fifo_queue_len < cap ? pb->fifo_queue_len : cap;
  first = pb->fifo_queue_cap - pb->fifo_queue_head;
  if (first > take) {
    first = take;
  }

  memcpy(buf, pb->fifo_queue + pb->fifo_queue_head, first);
  if (take > first) {
    memcpy(buf + first, pb->fifo_queue, take - first);
  }

  pb->fifo_queue_head = (pb->fifo_queue_head + take) %
                        pb->fifo_queue_cap;
  pb->fifo_queue_len -= take;
  return take;
}

static void *audio_playback_fifo_worker(void *arg)
{
  struct audio_playback *pb = (struct audio_playback *)arg;
  unsigned char buf[PB_FIFO_WRITE_CHUNK];

  while (1) {
    size_t take;
    int ret;

    pthread_mutex_lock(&pb->fifo_lock);
    while (pb->fifo_queue_len == 0 && !pb->fifo_thread_stop &&
           pb->fifo_error == 0) {
      pthread_cond_wait(&pb->fifo_cond, &pb->fifo_lock);
    }

    if (pb->fifo_error != 0 ||
        (pb->fifo_queue_len == 0 && pb->fifo_thread_stop)) {
      pthread_mutex_unlock(&pb->fifo_lock);
      break;
    }

    take = audio_playback_queue_pop_locked(pb, buf, sizeof(buf));
    pthread_mutex_unlock(&pb->fifo_lock);

    if (take == 0) {
      continue;
    }

    ret = audio_playback_write_fifo_direct(pb, buf, take);
    if (ret < 0) {
      pthread_mutex_lock(&pb->fifo_lock);
      if (pb->fifo_error == 0) {
        pb->fifo_error = ret;
      }
      pb->fallback_file = true;
      pb->fifo_thread_stop = true;
      pb->fifo_queue_len = 0;
      pthread_mutex_unlock(&pb->fifo_lock);
      syslog(LOG_WARNING, "[%s] fifo writer stopped: %d\n", TAG, ret);
      break;
    }
  }

  return NULL;
}

static int audio_playback_fifo_enqueue(struct audio_playback *pb,
                                       const unsigned char *buf,
                                       size_t len)
{
  if (pb == NULL || buf == NULL || len == 0 || !pb->fifo_started ||
      pb->fifo_queue == NULL) {
    return 0;
  }

  pthread_mutex_lock(&pb->fifo_lock);
  if (pb->fifo_error != 0 || pb->fifo_thread_stop) {
    pthread_mutex_unlock(&pb->fifo_lock);
    return 0;
  }

  if (len > pb->fifo_queue_cap - pb->fifo_queue_len) {
    pb->fifo_error = -ENOBUFS;
    pb->fallback_file = true;
    pb->fifo_thread_stop = true;
    pb->fifo_queue_len = 0;
    pthread_cond_signal(&pb->fifo_cond);
    pthread_mutex_unlock(&pb->fifo_lock);
    syslog(LOG_WARNING, "[%s] fifo queue full, use file fallback\n", TAG);
    return -ENOBUFS;
  }

  audio_playback_queue_append_locked(pb, buf, len);
  pthread_cond_signal(&pb->fifo_cond);
  pthread_mutex_unlock(&pb->fifo_lock);
  return 0;
}

static void audio_playback_stop_fifo_thread(struct audio_playback *pb)
{
  if (pb == NULL || !pb->fifo_thread_started) {
    return;
  }

  pthread_mutex_lock(&pb->fifo_lock);
  pb->fifo_thread_stop = true;
  pthread_cond_signal(&pb->fifo_cond);
  pthread_mutex_unlock(&pb->fifo_lock);

  pthread_join(pb->fifo_thread, NULL);
  pb->fifo_thread_started = false;
}

static void audio_playback_disable_fifo(struct audio_playback *pb)
{
  if (pb == NULL) {
    return;
  }

  audio_playback_stop_fifo_thread(pb);

  if (pb->fifo_fd >= 0) {
    close(pb->fifo_fd);
    pb->fifo_fd = -1;
  }

  if (pb->player != NULL) {
    nxplayer_release(pb->player);
    pb->player = NULL;
  }

  pb->fifo_started = false;
}
