    free(raw);

    /* Chunked decode — binary-safe, uses memmem instead of strstr.
     * Format: <hex-size>\r\n<data of hex-size bytes>\r\n ... 0\r\n */
    if (chunked) {
        char *src = resp_buf;
        char *end = resp_buf + resp_pos;
        char *dst = resp_buf;

        while (src < end) {
