  /* Set PWM channel */
  switch (haudio->init.output_chan) {
  case AUDIO_OUTPUT_CHAN_PWM1:
    audio_set_pwm1(haudio);
    break;
  case AUDIO_OUTPUT_CHAN_PWM0_PWM1:
    audio_set_pwm0(haudio);
    audio_set_pwm1(haudio);
