  unsigned int group;
  unsigned int pin;

  group = GPIO_GROUP(priv->gpio_pa);
  pin = GPIO_GROUP_PIN(priv->gpio_pa);

#ifdef CONFIG_AIC_AUDIO_EN_PIN_HIGH
  hal_gpio_clr_output(group, pin);
#else
  hal_gpio_set_output(group, pin);
#endif
}

