static unsigned int cfg_get_uint(const char *key, unsigned int def)
{
  char buf[32];
  char *endp;
  unsigned long value;

  if (claw_config_get(key, buf, sizeof(buf)) != OK || buf[0] == '\0') {
    return def;
  }

  value = strtoul(buf, &endp, 10);
  if (endp == buf || value == 0 || value > 600000) {
    return def;
  }

  return (unsigned int)value;
}

static void cfg_get_string(const char *key, const char *def,
                           char *buf, size_t cap)
{
  if (cap == 0) {
    return;
  }

  if (claw_config_get(key, buf, cap) == OK && buf[0] != '\0') {
    return;
  }

  snprintf(buf, cap, "%s", def ? def : "");
}

static bool text_has(const char *text, const char *needle)
{
  return text != NULL && needle != NULL && needle[0] != '\0' &&
         strstr(text, needle) != NULL;
}

static const char *skip_prompt_gap(const char *p)
{
  while (p != NULL && *p != '\0') {
    unsigned char c = (unsigned char)*p;

    if (c == ' ' || c == '\t' || c == '\r' || c == '\n' ||
        c == ',' || c == '.' || c == '?' || c == '!' ||
        c == ':' || c == ';') {
      p++;
      continue;
    }
    if (strncmp(p, "，", strlen("，")) == 0 ||
        strncmp(p, "。", strlen("。")) == 0 ||
        strncmp(p, "？", strlen("？")) == 0 ||
        strncmp(p, "！", strlen("！")) == 0 ||
        strncmp(p, "：", strlen("：")) == 0 ||
        strncmp(p, "；", strlen("；")) == 0) {
      p += strlen("，");
      continue;
    }
    break;
  }

  return p == NULL ? "" : p;
}

static const char *find_wake_remainder(const char *text)
{
  const char *p;
  const char *q;

  if (text == NULL) {
    return NULL;
  }

  if (s_voice.wake_word[0] != '\0') {
    p = strstr(text, s_voice.wake_word);
    if (p != NULL) {
      return skip_prompt_gap(p + strlen(s_voice.wake_word));
    }
  }

  p = strstr(text, "大王");
  if (p == NULL) {
    return NULL;
  }

  q = strstr(p + strlen("大王"), "大王");
  if (q == NULL || (size_t)(q - p) > strlen("大王") + 16) {
    return NULL;
  }

  return skip_prompt_gap(q + strlen("大王"));
}

