  if (ret < 0) {
    syslog(LOG_ERR, "[%s] aic_dma_chan_register failed: %d\n", TAG, ret);
    return ret;
  }
  cap->dma_registered = true;
  return 0;
}

static int capture_audio_prepare(struct audio_capture *cap,
                                 unsigned int sample_rate,
                                 unsigned int channels)
{
