  cap->audio.init.samplebits = AUDIO_SAMPLEBITS_16BIT;
  cap->audio.init.samplerate = (hal_audio_samplerate_e)sample_rate;
  cap->audio.init.channel = channels == 1
                              ? AUDIO_CHANNEL_MONO
                              : AUDIO_CHANNEL_STEREO;
  cap->audio.rxdma = &cap->rx_chan.hal;

