static unsigned char *wrap_pcm_as_wav(const unsigned char *pcm,
                                      size_t pcm_len,
                                      size_t *wav_len)
{
  const uint32_t sample_rate = VELACLAW_VOICE_SAMPLE_RATE;
  const uint16_t channels = VELACLAW_VOICE_CHANNELS;
  const uint16_t bits = VELACLAW_VOICE_BITS;
  const uint16_t block_align = channels * bits / 8;
  const uint32_t byte_rate = sample_rate * block_align;
  unsigned char *wav;

  if (pcm == NULL || pcm_len == 0 || wav_len == NULL ||
      pcm_len > UINT32_MAX - 44) {
    return NULL;
  }

  wav = malloc(pcm_len + 44);
  if (wav == NULL) {
    return NULL;
  }

  memcpy(wav, "RIFF", 4);
  put_le32(wav + 4, (uint32_t)(pcm_len + 36));
  memcpy(wav + 8, "WAVEfmt ", 8);
  put_le32(wav + 16, 16);
  put_le16(wav + 20, 1);
  put_le16(wav + 22, channels);
  put_le32(wav + 24, sample_rate);
  put_le32(wav + 28, byte_rate);
  put_le16(wav + 32, block_align);
  put_le16(wav + 34, bits);
  memcpy(wav + 36, "data", 4);
  put_le32(wav + 40, (uint32_t)pcm_len);
  memcpy(wav + 44, pcm, pcm_len);
  *wav_len = pcm_len + 44;
  return wav;
}

static char *build_asr_body(const unsigned char *pcm, size_t pcm_len,
                            size_t *body_len)
{
  static const char suffix[] = "\",\"format\":\"wav\"}}]}],\"stream\":false}";
  char prefix[256];
  unsigned char *wav = NULL;
  size_t wav_len = 0;
  size_t b64_len;
  size_t enc_len = 0;
  size_t prefix_len;
  size_t total;
  char *body;
  int ret;

  wav = wrap_pcm_as_wav(pcm, pcm_len, &wav_len);
  if (wav == NULL) {
    return NULL;
  }

  ret = snprintf(prefix, sizeof(prefix),
                 "{\"model\":\"%s\",\"messages\":[{\"role\":\"user\","
                 "\"content\":[{\"type\":\"input_audio\","
                 "\"input_audio\":{\"data\":\"data:audio/wav;base64,",
                 s_model);
  if (ret < 0 || (size_t)ret >= sizeof(prefix)) {
    free(wav);
    return NULL;
  }

  prefix_len = (size_t)ret;
  b64_len = ((wav_len + 2) / 3) * 4;
  total = prefix_len + b64_len + sizeof(suffix) - 1;

  body = malloc(total + 1);
  if (body == NULL) {
    free(wav);
    return NULL;
  }

  memcpy(body, prefix, prefix_len);
  ret = mbedtls_base64_encode((unsigned char *)body + prefix_len,
                              b64_len + 1, &enc_len, wav, wav_len);
  free(wav);
  if (ret != 0 || enc_len != b64_len) {
    free(body);
    return NULL;
  }

  memcpy(body + prefix_len + enc_len, suffix, sizeof(suffix) - 1);
  body[total] = '\0';
  if (body_len) {
    *body_len = total;
  }
  return body;
}

static const char *json_string_at(cJSON *root, const char *a,
                                  const char *b, const char *c,
                                  const char *d)
{
  cJSON *item = root;

  if (a) {
    item = cJSON_GetObjectItem(item, a);
  }
  if (item && b) {
    item = cJSON_GetObjectItem(item, b);
  }
  if (item && c) {
    item = cJSON_GetObjectItem(item, c);
  }
  if (item && d) {
    item = cJSON_GetObjectItem(item, d);
  }

  return item && cJSON_IsString(item) ? item->valuestring : NULL;
}

static int copy_json_content(cJSON *content, char *out, size_t out_cap)
{
  size_t used = 0;

  if (content == NULL || out == NULL || out_cap == 0) {
  if (content == NULL || out == NULL || out_cap == 0) {
    return -EINVAL;
  }

  out[0] = '\0';

  if (cJSON_IsString(content)) {
    snprintf(out, out_cap, "%s", content->valuestring);
    return out[0] ? 0 : -ENODATA;
  }

  if (cJSON_IsArray(content)) {
    int count = cJSON_GetArraySize(content);

    for (int i = 0; i < count && used + 1 < out_cap; i++) {
      cJSON *item = cJSON_GetArrayItem(content, i);
      const char *s = json_string_at(item, "text", NULL, NULL, NULL);

      if (s == NULL) {
        s = json_string_at(item, "input_text", NULL, NULL, NULL);
      }
      if (s == NULL) {
        s = json_string_at(item, "content", NULL, NULL, NULL);
      }
      if (s != NULL) {
        int n = snprintf(out + used, out_cap - used, "%s", s);

        if (n < 0) {
          return -EIO;
        }
        if ((size_t)n >= out_cap - used) {
          used = out_cap - 1;
          break;
        }
        used += (size_t)n;
      }
    }

    return out[0] ? 0 : -ENODATA;
  }

  return -ENODATA;
}

static int parse_asr_response(const char *resp, char *text, size_t text_cap)
{
  cJSON *root;
  cJSON *choices;
  cJSON *choice;
  cJSON *message;
  cJSON *content;
  const char *direct;
  int ret;

  if (resp == NULL || text == NULL || text_cap == 0) {
    return -EINVAL;
  }

  text[0] = '\0';
  root = cJSON_Parse(resp);
  if (root == NULL) {
    return -EPROTO;
  }

  choices = cJSON_GetObjectItem(root, "choices");
  choice = cJSON_GetArrayItem(choices, 0);
  message = choice ? cJSON_GetObjectItem(choice, "message") : NULL;
  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
  ret = copy_json_content(content, text, text_cap);
  if (ret == 0) {
    cJSON_Delete(root);
    return 0;
  }

  direct = json_string_at(root, "text", NULL, NULL, NULL);
  if (direct == NULL) {
    direct = json_string_at(root, "result", "text", NULL, NULL);
  }
  if (direct == NULL) {
    direct = json_string_at(root, "data", "text", NULL, NULL);
  }

  if (direct != NULL) {
    snprintf(text, text_cap, "%s", direct);
    ret = text[0] ? 0 : -ENODATA;
  }

  cJSON_Delete(root);
  return ret;
}

static int mimo_asr_recognize(const unsigned char *pcm_data,
                              size_t pcm_len,
                              char *text_out,
                              size_t text_cap)
{
  char *body;
  char *resp;
  char auth[192];
  size_t body_len = 0;
  size_t resp_len = 0;
  int status;
  int ret;

  if (pcm_data == NULL || pcm_len == 0 || text_out == NULL ||
      text_cap == 0) {
    return -EINVAL;
  }

  mimo_asr_init();
  if (s_api_key[0] == '\0') {
    syslog(LOG_ERR, "[%s] API key not configured\n", TAG);
    return -ENOENT;
  }

  body = build_asr_body(pcm_data, pcm_len, &body_len);
  if (body == NULL) {
    return -ENOMEM;
  }

  resp = calloc(1, VELACLAW_VOICE_RESP_BUF_SIZE);
  if (resp == NULL) {
    free(body);
    return -ENOMEM;
  }

  snprintf(auth, sizeof(auth), "Bearer %s", s_api_key);
  vela_header_t hdrs[] = {
    { "Content-Type", "application/json" },
    { "Authorization", auth },
    { "api-key", s_api_key },
    { "Connection", "close" },
    { NULL, NULL }
  };

  syslog(LOG_INFO, "[%s] request %zu bytes pcm via %s/%s\n",
         TAG, pcm_len, s_host, s_model);
  status = vela_https_request(s_host, s_port, "POST", s_path,
                              hdrs, body, body_len,
                              resp, VELACLAW_VOICE_RESP_BUF_SIZE,
                              &resp_len);
  free(body);

  if (status != 200) {
    syslog(LOG_ERR, "[%s] HTTP %d: %.160s\n", TAG, status, resp);
    free(resp);
    return -EIO;
  }

  ret = parse_asr_response(resp, text_out, text_cap);
  free(resp);
  if (ret != 0) {
    syslog(LOG_WARNING, "[%s] parse failed: %d\n", TAG, ret);
    return ret;
  }

  syslog(LOG_INFO, "[%s] recognized: %.80s\n", TAG, text_out);
  return 0;
}

