/* ── File-based helpers (kept for QEMU test commands) ──── */

static int read_pcm_file(const char* path,
    unsigned char** out, size_t* out_len)
{
    int fd = open(path, O_RDONLY);

    if (fd < 0) {
        syslog(LOG_ERR, "[%s] Cannot open %s: %d\n",
            TAG, path, errno);
        return -errno;
    }

    off_t fsize = lseek(fd, 0, SEEK_END);

    if (fsize <= 0 || (size_t)fsize > VELACLAW_VOICE_PCM_BUF_SIZE) {
        syslog(LOG_ERR, "[%s] File too large or empty: %ld\n",
            TAG, (long)fsize);
        close(fd);
        return -EFBIG;
    }

    lseek(fd, 0, SEEK_SET);

    unsigned char* buf = malloc((size_t)fsize);

    if (!buf) {
        close(fd);
        return -ENOMEM;
    }

    ssize_t nread = read(fd, buf, (size_t)fsize);

    close(fd);

    if (nread != (ssize_t)fsize) {
        free(buf);
        return -EIO;
    }

    *out = buf;
    *out_len = (size_t)fsize;
    return 0;
}

static int write_pcm_file(const char* path,
    const unsigned char* data, size_t len)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);

    if (fd < 0) {
        syslog(LOG_ERR, "[%s] Cannot create %s: %d\n",
            TAG, path, errno);
        return -errno;
    }

    ssize_t nw = write(fd, data, len);

    close(fd);
    return (nw == (ssize_t)len) ? 0 : -EIO;
}

/* ── Recording thread (PTT mode — streaming ASR) ─────────── */

static void* recording_thread(void* arg)
{
    (void)arg;
    unsigned char chunk[VELACLAW_ASR_CHUNK_SIZE];
    int need_fallback = 0;

    syslog(LOG_INFO, "[%s] recording thread started (streaming)\n",
        TAG);

    /* Open streaming ASR session */
    voice_asr_stream_t* stream = voice_asr_stream_open();

    if (!stream) {
        syslog(LOG_WARNING,
            "[%s] streaming ASR unavailable, batch fallback\n",
            TAG);
        need_fallback = 1;

        /* Lazy-allocate PCM buffer for batch fallback */
        pthread_mutex_lock(&s_voice.lock);
        if (!s_voice.pcm_buf) {
            s_voice.pcm_buf = malloc(s_voice.pcm_cap);
            if (!s_voice.pcm_buf) {
                syslog(LOG_ERR,
                    "[%s] fallback buffer alloc failed\n", TAG);
                pthread_mutex_unlock(&s_voice.lock);
                return NULL;
            }
            s_voice.pcm_len = 0;
        }
        pthread_mutex_unlock(&s_voice.lock);
    }

    while (1) {
        pthread_mutex_lock(&s_voice.lock);
        enum voice_state st = s_voice.state;
        pthread_mutex_unlock(&s_voice.lock);

        if (st != VOICE_RECORDING) {
            break;
        }

        int n = audio_capture_read(s_voice.cap, chunk, sizeof(chunk));

        if (n <= 0) {
            break;
