int voice_tts_speak_stream(const char* text,
    voice_tts_chunk_cb cb,
    void* user_data)
{
    if (!s_active) {
        syslog(LOG_ERR, "[%s] No TTS backend for streaming\n", TAG);
        return -ENODEV;
    }

    if (s_active->synthesize_stream) {
        return s_active->synthesize_stream(text, cb, user_data);
    }

    if (!s_active->synthesize) {
        return -ENOSYS;
    }

    unsigned char* pcm = malloc(VELACLAW_VOICE_PCM_BUF_SIZE);
    if (!pcm) {
        return -ENOMEM;
    }

    size_t pcm_len = 0;
    int ret = s_active->synthesize(text, pcm,
        VELACLAW_VOICE_PCM_BUF_SIZE, &pcm_len);
    if (ret == 0 && pcm_len > 0) {
        cb(pcm, pcm_len, 0, user_data);
        cb(NULL, 0, 1, user_data);
    }
    free(pcm);
    return ret;
}
