{
  return text_has(text, "退出") ||
         text_has(text, "结束对话") ||
         text_has(text, "停止对话") ||
         text_has(text, "关闭对话") ||
         text_has(text, "不用了");
}

static int push_voice_prompt(const char *text)
{
  velaclaw_msg_t msg;

  if (text == NULL || text[0] == '\0') {
    return -EINVAL;
  }

  memset(&msg, 0, sizeof(msg));
  snprintf(msg.channel, sizeof(msg.channel), "%s", VELACLAW_CHAN_VOICE);
  snprintf(msg.chat_id, sizeof(msg.chat_id), "%s", "voice");
  msg.content = strdup(text);
  if (msg.content == NULL) {
    return -ENOMEM;
  }

  if (message_bus_push_inbound(&msg) != OK) {
    free(msg.content);
    return -EIO;
  }

  return 0;
}

