    char tmp[32] = { 0 };
    if (claw_config_get(CFG_KEY_ROUTER_PROFILE, tmp, sizeof(tmp)) == 0) {
        if (strcmp(tmp, "eco") == 0) {
            s_profile = LLM_ROUTE_ECO;
        } else if (strcmp(tmp, "premium") == 0) {
