  (void)is_last;

  if (pcm_data != NULL && pcm_len > 0 && ctx != NULL && ctx->pb != NULL) {
    int ret = audio_playback_write(ctx->pb, pcm_data, pcm_len);
    if (ret < 0 && ctx->write_error == 0) {
