static int read_pcm_file(const char *path,
                         unsigned char **out, size_t *out_len)
{
  int fd;
  off_t fsize;
  unsigned char *buf;
  ssize_t nread;

  if (path == NULL || out == NULL || out_len == NULL) {
    return -EINVAL;
  }

  fd = open(path, O_RDONLY);
  if (fd < 0) {
    return -errno;
  }

  fsize = lseek(fd, 0, SEEK_END);
  if (fsize <= 0 || (size_t)fsize > VOICE_TEST_MAX_PCM_BYTES) {
    close(fd);
    return -EFBIG;
  }
  lseek(fd, 0, SEEK_SET);

  buf = malloc((size_t)fsize);
  if (buf == NULL) {
    close(fd);
    return -ENOMEM;
  }

  nread = read(fd, buf, (size_t)fsize);
  close(fd);
  if (nread != (ssize_t)fsize) {
    free(buf);
    return -EIO;
  }

  *out = buf;
  *out_len = (size_t)fsize;
  return 0;
}

static int write_pcm_file(const char *path,
                          const unsigned char *data, size_t len)
{
  int fd;
  size_t off = 0;

  if (path == NULL || data == NULL) {
    return -EINVAL;
  }

  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (fd < 0) {
    return -errno;
  }

  while (off < len) {
    ssize_t nw = write(fd, data + off, len - off);
    if (nw < 0) {
      if (errno == EINTR) {
        continue;
      }
      close(fd);
      return -errno;
    }
    if (nw == 0) {
      close(fd);
      return -EIO;
    }
    off += (size_t)nw;
  }

  close(fd);
  return 0;
}

